/* ── Particles ── */
function Particles() {
  const ref = useRef(null);
  useEffect(() => {
    const c = ref.current, ctx = c.getContext("2d");
    let W = c.width = window.innerWidth, H = c.height = window.innerHeight;
    const pts = Array.from({length:90},()=>({
      x:Math.random()*W, y:Math.random()*H,
      r:Math.random()*1.5+0.3,
      vx:(Math.random()-.5)*.22, vy:(Math.random()-.5)*.22,
      a:Math.random()*.8+.1,
    }));
    let raf;
    const tick=()=>{
      ctx.clearRect(0,0,W,H);
      pts.forEach(p=>{
        p.x+=p.vx; p.y+=p.vy;
        if(p.x<0)p.x=W; if(p.x>W)p.x=0;
        if(p.y<0)p.y=H; if(p.y>H)p.y=0;
        ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
        ctx.fillStyle=`rgba(107,147,201,${p.a*.4})`; ctx.fill();
      });
      for(let i=0;i<pts.length;i++) for(let j=i+1;j<pts.length;j++){
        const dx=pts[i].x-pts[j].x,dy=pts[i].y-pts[j].y,d=Math.sqrt(dx*dx+dy*dy);
        if(d<120){ctx.beginPath();ctx.moveTo(pts[i].x,pts[i].y);ctx.lineTo(pts[j].x,pts[j].y);
          ctx.strokeStyle=`rgba(107,147,201,${.065*(1-d/120)})`;ctx.lineWidth=.65;ctx.stroke();}
      }
      raf=requestAnimationFrame(tick);
    };
    tick();
    const onR=()=>{W=c.width=window.innerWidth;H=c.height=window.innerHeight;};
    window.addEventListener("resize",onR);
    return()=>{cancelAnimationFrame(raf);window.removeEventListener("resize",onR);};
  },[]);
  return <canvas ref={ref} style={{position:"fixed",inset:0,zIndex:1,pointerEvents:"none"}}/>;
}

/* ── Counter ── */
function Counter({to,suffix=""}) {
  const [v,setV]=useState(0);
  useEffect(()=>{
    let s=0; const step=Math.ceil(to/45);
    const t=setInterval(()=>{s+=step; if(s>=to){setV(to);clearInterval(t);}else setV(s);},30);
    return()=>clearInterval(t);
  },[to]);
  return <>{v}{suffix}</>;
}

/* ── 3D Photo Card ── */
function PhotoCard({item,i}) {
  const [rot,setRot]=useState({x:0,y:0});
  const [hov,setHov]=useState(false);
  const ref=useRef(null);

  const onMove=e=>{
    const r=ref.current.getBoundingClientRect();
    const x=((e.clientX-r.left)/r.width-.5)*22;
    const y=-((e.clientY-r.top)/r.height-.5)*22;
    setRot({x:y,y:x});
  };

  return (
    <div ref={ref}
      onMouseMove={onMove}
      onMouseEnter={()=>setHov(true)}
      onMouseLeave={()=>{setRot({x:0,y:0});setHov(false);}}
      style={{
        perspective:800,
        cursor:"pointer",
      }}>
      <div style={{
        background:`linear-gradient(145deg, rgba(15,26,48,0.9), rgba(8,16,32,0.95))`,
        border:`1px solid ${hov ? item.color+"60" : "rgba(107,147,201,0.15)"}`,
        borderRadius:20,
        padding:"28px 22px",
        position:"relative", overflow:"hidden",
        transform:`rotateX(${rot.x}deg) rotateY(${rot.y}deg) ${hov?"scale(1.04)":"scale(1)"}`,
        transition: hov?"transform .1s ease":"transform .5s cubic-bezier(.22,1,.36,1)",
        boxShadow: hov
          ? `0 24px 60px rgba(0,0,0,.5), 0 0 0 1px ${item.color}40 inset, 0 0 40px ${item.color}20`
          : "0 8px 30px rgba(0,0,0,.3)",
        transformStyle:"preserve-3d",
      }}>
        {/* glow spot */}
        <div style={{
          position:"absolute", top:-30, right:-30,
          width:100, height:100, borderRadius:"50%",
          background:`radial-gradient(circle, ${item.color}30, transparent 70%)`,
          filter:"blur(20px)",
          opacity: hov?1:.4, transition:"opacity .3s",
        }}/>
        {/* shine layer */}
        <div style={{
          position:"absolute",inset:0,borderRadius:20,
          background:"linear-gradient(135deg,rgba(255,255,255,.06) 0%,transparent 50%)",
          opacity:hov?1:0, transition:"opacity .3s",
          pointerEvents:"none",
        }}/>
        <div style={{
          marginBottom:16,
          filter:`drop-shadow(0 0 12px ${item.color}80)`,
          transform:"translateZ(20px)",
          display:"block",
          color:item.color,
        }}>{item.icon}</div>
        <div style={{
          fontSize:15, fontWeight:700, color:"#fff",
          marginBottom:6, transform:"translateZ(15px)",
          fontFamily:"'Playfair Display',serif",
        }}>{item.label}</div>
        <div style={{
          fontSize:11, color:"#4a6a8a", letterSpacing:"1px",
          transform:"translateZ(10px)",
        }}>{item.desc}</div>
        {/* bottom bar */}
        <div style={{
          position:"absolute",bottom:0,left:0,right:0,height:2,
          background:`linear-gradient(90deg,transparent,${item.color},transparent)`,
          opacity:hov?1:0, transition:"opacity .3s",
        }}/>
      </div>
    </div>
  );
}

