/* ── Scroll Progress Bar ── */
function ScrollProgress() {
  const [pct, setPct] = useState(0);
  useEffect(() => {
    const onScroll = () => {
      const el = document.documentElement;
      setPct((el.scrollTop / (el.scrollHeight - el.clientHeight)) * 100);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return (
    <div style={{
      position:"fixed", top:0, left:0, width:`${pct}%`, height:2,
      background:"linear-gradient(90deg,#2e4a8a,#6b93c9,#a8c0dc)",
      zIndex:200, transition:"width .1s linear", pointerEvents:"none",
      boxShadow:"0 0 8px rgba(107,147,201,.6)",
    }}/>
  );
}

/* ── Cursor Glow ── */
function CursorGlow() {
  const [pos, setPos] = useState({x:-999, y:-999});
  useEffect(() => {
    const onMove = e => setPos({x: e.clientX, y: e.clientY});
    window.addEventListener("mousemove", onMove);
    return () => window.removeEventListener("mousemove", onMove);
  }, []);
  return (
    <div style={{
      position:"fixed",
      left: pos.x - 220, top: pos.y - 220,
      width:440, height:440,
      borderRadius:"50%",
      background:"radial-gradient(circle, rgba(107,147,201,.08) 0%, transparent 65%)",
      pointerEvents:"none",
      zIndex:2,
      transition:"left .12s ease, top .12s ease",
    }}/>
  );
}

/* ── Scroll Reveal ── */
function useReveal(threshold=0.12) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { setVisible(true); obs.disconnect(); } },
      { threshold }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, visible];
}

function Reveal({ children, delay=0, y=36 }) {
  const [ref, visible] = useReveal();
  return (
    <div ref={ref} style={{
      opacity: visible ? 1 : 0,
      transform: visible ? "translateY(0)" : `translateY(${y}px)`,
      transition: `opacity .7s ${delay}s ease, transform .7s ${delay}s cubic-bezier(.22,1,.36,1)`,
    }}>
      {children}
    </div>
  );
}

