function useLivePrices() {
  const [prices, setPrices] = useState({ BTC:null, ETH:null, EURUSD:null, BTC_CHG:null, ETH_CHG:null });
  useEffect(() => {
    const load = async () => {
      try {
        const [btcRes, ethRes, eurRes] = await Promise.all([
          fetch("https://api.binance.com/api/v3/ticker/24hr?symbol=BTCUSDT"),
          fetch("https://api.binance.com/api/v3/ticker/24hr?symbol=ETHUSDT"),
          fetch("https://api.binance.com/api/v3/ticker/price?symbol=EURUSDT"),
        ]);
        const [btc, eth, eur] = await Promise.all([btcRes.json(), ethRes.json(), eurRes.json()]);
        setPrices({
          BTC: parseFloat(btc.lastPrice),
          ETH: parseFloat(eth.lastPrice),
          BTC_CHG: parseFloat(btc.priceChangePercent),
          ETH_CHG: parseFloat(eth.priceChangePercent),
          EURUSD: parseFloat(eur.price),
        });
      } catch(e) { console.error("Ticker fetch failed:", e); }
    };
    load();
    const id = setInterval(load, 30000);
    return () => clearInterval(id);
  }, []);
  return prices;
}

